#!/usr/bin/python3
"""Post-flight plots ONLY: truth is read here solely as an independent evaluator."""
import sys,json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
root=Path('/work/cartographer/v2');out=root/'results'/sys.argv[1];f=json.loads((out/'flight.json').read_text());judge=json.loads((out/'judge.json').read_text());ev=json.loads((out/('evaluation-offline.json' if (out/'evaluation-offline.json').exists() else 'evaluation.json')).read_text());g=np.array(judge['poses']);tr=f['trace'];t=np.array([p['stamp'] for p in tr]);a=np.array([p['position'] for p in tr]);b=np.array([np.interp(t,g[:,0],g[:,i]) for i in [1,2,3]]).T;err=np.linalg.norm(a-b,axis=1);start=judge['result'].get('start_time_s',t[0]);metrics={'navigation_pose':'CAD/observed-line/window-corrected body pose used by the mission','alignment':'direct CAD coordinates; no post-fit alignment','samples':len(t),'rmse_m':float(np.sqrt(np.mean(err**2))),'p95_m':float(np.percentile(err,95)),'max_m':float(err.max()),'truth_use':'independent evaluation only; never navigation input'}
(out/'metrics.json').write_text(json.dumps({'judge':judge['result'],'navigation':metrics,'continuous_local_odometry':ev['summary'],'passive_window_corrections':len(f.get('window_registration',[]))},indent=2))
(out/'navigation-comparison.json').write_text(json.dumps({'scope':'offline evaluator only','time_s':t.tolist(),'navigation_body_xyz':a.tolist(),'evaluation_body_xyz':b.tolist(),'error_m':err.tolist()},indent=2))
plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False});fig=plt.figure(figsize=(13,7),layout='constrained');gs=fig.add_gridspec(2,2,width_ratios=[1.05,1]);ax=fig.add_subplot(gs[:,0]);data=np.load('/work/cartographer/results/cad-grid.npz');surface=data['surface'];origin=data['origin'];res=float(data['res']);z=int(round((.762-origin[2])/res));xy=surface[:,:,z];ax.imshow(xy.T,origin='lower',extent=[origin[0],origin[0]+xy.shape[0]*res,origin[1],origin[1]+xy.shape[1]*res],cmap='Greys',alpha=.38,vmin=0,vmax=1)
ax.plot(g[:,1],g[:,2],color='#f39c32',lw=2.6,label='Independent flight trace');ax.plot(a[:,0],a[:,1],color='#146cc2',lw=1.2,ls='--',label='Navigation estimate');ax.scatter(g[0,1],g[0,2],s=45,color='#16976f',label='Launch');pad=plt.Circle((-2.04216,-.79248),.762,fill=False,color='#16976f',lw=1.5);ax.add_patch(pad);ax.set(xlim=(-3.2,3.2),ylim=(-3.2,3.2),xlabel='Published CAD x (m)',ylabel='Published CAD y (m)',title='Flight verification over CAD prior (not the SLAM map)',aspect='equal');ax.legend(loc='upper left',fontsize=8)
ax=fig.add_subplot(gs[0,1]);ax.plot(t-start,err*100,color='#146cc2',lw=1.4);ax.set(xlabel='Seconds from departure',ylabel='3D navigation error (cm)',title=f"Navigation RMSE {metrics['rmse_m']*100:.1f} cm; maximum {metrics['max_m']*100:.1f} cm");ax.grid(alpha=.2);
ax=fig.add_subplot(gs[1,1]);ax.plot(t-start,b[:,2],color='#f39c32',label='Independent body height');ax.plot(t-start,a[:,2],color='#146cc2',ls='--',label='Navigation body height');ax.set(xlabel='Seconds from departure',ylabel='Body height (m)',title='Height continuity through tunnel and window');ax.grid(alpha=.2);ax.legend(fontsize=8)
r=judge['result'];fig.suptitle(f"{sys.argv[1]}  |  {'PASS' if r['engineering_complete'] else 'FAIL'}  |  {r.get('elapsed_s',0):.2f} s  |  {r['collision_events']} contacts  |  GPS off",fontsize=15,fontweight='bold');fig.savefig(out/'flight-evidence.png',dpi=160);print(json.dumps(metrics,indent=2))
